{
  "table": {
    "name": "foreign_data",
    "purpose": "Localized (non-English) card data for a Magic: The Gathering card database. One row per card per language/printing, holding the translated name, rules text, flavor text and type line, plus the language and the printing's Gatherer multiverseid. Each row links back to a card in `cards` via `uuid` (many foreign rows per card). Empty strings (rather than NULLs) are used when a card has no text/flavor/type in that language, and some rows exist only as stubs (name only, no multiverseid)."
  },
  "columns": {
    "flavorText": {
      "role": "free_text",
      "name": "flavorText",
      "description": "The card's flavor text translated into the row's language (e.g. German, Japanese, Spanish, French, Russian, Korean, Portuguese). Empty string when the printing has no flavor text (~44% of rows).",
      "status": "resolved"
    },
    "id": {
      "role": "identifier",
      "name": "id",
      "description": "Surrogate primary key / row identifier for this table (sequential integers 1–229205, one per row). The statistically accepted joins to cards.tcgplayerProductId, cards.cardKingdomId, cards.cardKingdomFoilId and cards.mcmMetaId are almost certainly coincidental numeric overlaps with unrelated vendor product IDs, not real relationships.",
      "status": "resolved"
    },
    "language": {
      "role": "category",
      "name": "language",
      "description": "Human-readable name of the language this localization is in. 16 values: the core MTG languages (Japanese, French, German, Italian, Spanish, Portuguese (Brazil), Russian, Korean, Chinese) plus rare promotional ones (Ancient Greek, Sanskrit, Latin, Hebrew, etc.).",
      "status": "resolved"
    },
    "multiverseid": {
      "role": "identifier",
      "name": "multiverseid",
      "description": "The Gatherer 'multiverseid' of this specific foreign-language printing (Wizards of the Coast's identifier for an individual printed card). NULL for ~17% of rows — printings not catalogued in Gatherer (e.g. promotional or stub entries). Nearly unique per row, with a handful of duplicates.",
      "status": "resolved"
    },
    "name": {
      "role": "free_text",
      "name": "name",
      "description": "The card's name translated into the row's language (e.g. 'Zyklop vom Blutfelsen', '霊紋の振り子', 'Pacifismo'). Repeats reflect common cards printed in many languages/sets.",
      "status": "resolved"
    },
    "text": {
      "role": "free_text",
      "name": "text",
      "description": "The card's rules/abilities text in the row's language, with line breaks and mana/reminder notation preserved. Empty string for cards with no rules text (~16% of rows).",
      "status": "resolved"
    },
    "type": {
      "role": "free_text",
      "name": "type",
      "description": "The card's type line translated into the row's language (e.g. 'Kreatur — Zyklop' = Creature — Cyclops, 'Criatura Lendária — Guerreiro Goblin' = Legendary Creature — Goblin Warrior). Empty string when the type line was not localized for that printing.",
      "status": "resolved"
    },
    "uuid": {
      "role": "foreign_key",
      "name": "uuid",
      "description": "Foreign key to cards.uuid identifying the (English) card/face whose localization this row holds. Many-to-one: a card typically has one row per language (up to ~10 rows share a uuid; 34,056 distinct cards across 229,186 rows).",
      "status": "resolved"
    }
  }
}
